INSERT INTO `item_template_locale`
    (`ID`, `locale`, `Name`, `Description`, `VerifiedBuild`)
VALUES
(7770000, 'deDE', 'Abzeichen der Sengenden Klinge', 'Ein geschwärztes Eisenabzeichen der Kultisten der Sengenden Klinge. Die Kor''kron zählen sie, um zu wissen, wie viele noch übrig sind.', 0),
(7770000, 'esES', 'Insignia de Hoja abrasadora', 'Una insignia de hierro ennegrecido que llevan los fieles de la Hoja abrasadora. Los Kor''kron las cuentan para saber cuántos quedan.', 0),
(7770000, 'esMX', 'Insignia de Hoja abrasadora', 'Una insignia de hierro ennegrecido que llevan los fieles de la Hoja abrasadora. Los Kor''kron las cuentan para saber cuántos quedan.', 0),
(7770000, 'frFR', 'Insigne de la Lame brûlante', 'Un insigne de fer noirci porté par les sectateurs de la Lame brûlante. Les Kor''kron les comptent pour savoir combien il en reste.', 0),
(7770000, 'koKR', '이글거리는 칼날단 휘장', '이글거리는 칼날단 이교도가 달던 검게 그을린 쇠 휘장입니다. 코르크론은 이것을 세어 남은 이교도의 수를 가늠합니다.', 0),
(7770000, 'ruRU', 'Значок Огненного Клинка', 'Почерневший железный значок сектанта из клана Огненного Клинка. Кор''кроны считают такие значки, чтобы знать, сколько сектантов осталось.', 0),
(7770001, 'deDE', 'Goldnugget aus den Todesminen', 'Vor dem Ersten Krieg waren die Todesminen die reichsten Goldminen Sturmwinds. Dieses Nugget stammt aus einer Ader, die die Defias nie gefunden haben.', 0),
(7770001, 'esES', 'Pepita de oro de las Minas de la Muerte', 'Antes de la Primera Guerra, las Minas de la Muerte eran las minas de oro más ricas de Ventormenta. Esta pepita procede de una veta que los Defias nunca encontraron.', 0),
(7770001, 'esMX', 'Pepita de oro de las Minas de la Muerte', 'Antes de la Primera Guerra, las Minas de la Muerte eran las minas de oro más ricas de Ventormenta. Esta pepita procede de una veta que los Defias nunca encontraron.', 0),
(7770001, 'frFR', 'Pépite d''or des Mortemines', 'Avant la Première Guerre, les Mortemines étaient les plus riches mines d''or de Hurlevent. Cette pépite vient d''un filon que les Défias n''ont jamais trouvé.', 0),
(7770001, 'koKR', '죽음의 폐광 금덩이', '1차 대전쟁 전, 죽음의 폐광은 스톰윈드에서 가장 풍요로운 금광이었습니다. 이 금덩이는 데피아즈단이 끝내 찾지 못한 광맥에서 나왔습니다.', 0),
(7770001, 'ruRU', 'Золотой самородок из Мертвых копей', 'До Первой войны Мертвые копи были богатейшими золотыми рудниками Штормграда. Этот самородок взят из жилы, которую так и не нашло Братство Справедливости.', 0),
(7770002, 'deDE', 'Siegelring der Familie Silberlein', 'Ein Siegelring mit dem Wappen von Baron Silberlein, dem Herrn der Burg vor Arugals Ankunft. Die Familie gibt es nicht mehr, aber ein Sammler würde trotzdem dafür zahlen.', 0),
(7770002, 'esES', 'Sello de la familia Filargenta', 'Un sello con el blasón del barón Filargenta, señor del castillo antes de la llegada de Arugal. La familia ya no existe, pero un coleccionista pagaría por él.', 0),
(7770002, 'esMX', 'Sello de la familia Filargenta', 'Un sello con el blasón del barón Filargenta, señor del castillo antes de la llegada de Arugal. La familia ya no existe, pero un coleccionista pagaría por él.', 0),
(7770002, 'frFR', 'Chevalière de la famille d''Argelaine', 'Une chevalière aux armes du baron d''Argelaine, seigneur du donjon avant l''arrivée d''Arugal. La famille n''est plus, mais un collectionneur paierait encore pour elle.', 0),
(7770002, 'koKR', '실버레인 가문의 인장 반지', '아루갈이 오기 전 성의 주인이던 실버레인 남작의 문장이 새겨진 인장 반지입니다. 가문은 사라졌지만 수집가라면 값을 치를 것입니다.', 0),
(7770002, 'ruRU', 'Печатка рода Сильверлейнов', 'Печатка с гербом барона Сильверлейна, хозяина крепости до прихода Аругала. Рода больше нет, но коллекционер все равно заплатит за нее.', 0),
(7770003, 'deDE', 'Muschel aus dem Mondtempel', 'Eine blasse Muschel von den Stufen des versunkenen Tempels der Elune. Im Mondlicht schimmert sie schwach.', 0),
(7770003, 'esES', 'Concha del templo lunar', 'Una concha pálida de los escalones del templo hundido de Elune. Reluce débilmente a la luz de la luna.', 0),
(7770003, 'esMX', 'Concha del templo lunar', 'Una concha pálida de los escalones del templo hundido de Elune. Reluce débilmente a la luz de la luna.', 0),
(7770003, 'frFR', 'Coquillage du temple lunaire', 'Un coquillage pâle venu des marches du temple englouti d''Élune. Il miroite faiblement au clair de lune.', 0),
(7770003, 'koKR', '달빛 사원의 조개껍질', '가라앉은 엘룬 사원의 계단에서 나온 창백한 조개껍질입니다. 달빛 아래에서 희미하게 반짝입니다.', 0),
(7770003, 'ruRU', 'Раковина из лунного храма', 'Бледная раковина со ступеней затонувшего храма Элуны. В лунном свете она едва заметно мерцает.', 0),
(7770004, 'deDE', 'Beschlagnahmtes Dietrichset', 'Eine Rolle feiner Dietriche der Defias, nach dem Aufstand aus einer Zelle geholt. Für ehrliche Bürger nutzlos, aber ein Händler kauft den Stahl.', 0),
(7770004, 'esES', 'Ganzúas confiscadas', 'Un rollo de finas ganzúas Defias sacado de una celda tras el motín. No sirven a un ciudadano honrado, pero un mercader comprará el acero.', 0),
(7770004, 'esMX', 'Ganzúas confiscadas', 'Un rollo de finas ganzúas Defias sacado de una celda tras el motín. No sirven a un ciudadano honrado, pero un mercader comprará el acero.', 0),
(7770004, 'frFR', 'Crochets confisqués', 'Un rouleau de fins crochets défias pris dans une cellule après l''émeute. Inutiles à un honnête citoyen, mais un marchand achètera l''acier.', 0),
(7770004, 'koKR', '압수한 자물쇠 따개 세트', '폭동 뒤 감방에서 압수한 데피아즈단의 고급 자물쇠 따개 꾸러미입니다. 정직한 시민에게는 쓸모없지만 상인은 강철 값을 쳐줄 것입니다.', 0),
(7770004, 'ruRU', 'Конфискованный набор отмычек', 'Сверток отличных отмычек Братства Справедливости, изъятый из камеры после бунта. Честному горожанину ни к чему, но торговец купит их ради стали.', 0),
(7770005, 'deDE', 'Agamaggans Dorn', 'Ein Dorn der großen Ranken der Klingenhauer, die laut den Stacheleber aus dem Blut des Halbgotts Agamaggan entsprossen. Sammler zahlen gut dafür.', 0),
(7770005, 'esES', 'Espina de Agamaggan', 'Una espina de las grandes enredaderas de Rajacieno, que según los jabaespines brotaron de la sangre del semidiós Agamaggan. Los coleccionistas pagan bien por ellas.', 0),
(7770005, 'esMX', 'Espina de Agamaggan', 'Una espina de las grandes enredaderas de Rajacieno, que según los jabaespines brotaron de la sangre del semidiós Agamaggan. Los coleccionistas pagan bien por ellas.', 0),
(7770005, 'frFR', 'Épine d''Agamaggan', 'Une épine des grandes lianes de Tranchebauge, nées selon les huranes du sang du demi-dieu Agamaggan. Les collectionneurs les paient bien.', 0),
(7770005, 'koKR', '아감마간의 가시', '가시덩굴의 거대한 덩굴에서 얻은 가시입니다. 가시멧돼지들은 이 덩굴이 반신 아감마간의 피에서 자랐다고 말합니다. 수집가들이 후한 값을 치릅니다.', 0),
(7770005, 'ruRU', 'Шип Агамаггана', 'Шип с огромных лоз Иглошкурых, выросших, как говорят свинобразы, из крови полубога Агамаггана. Коллекционеры хорошо платят за такие шипы.', 0),
(7770006, 'deDE', 'Frostwelke Dornenranke', 'Ein Stück der großen Dornenranke der Klingenhauer, geschwärzt von der Kälte des Lichs. Die Schamanen der Stacheleber gäben viel, um es zurückzubekommen.', 0),
(7770006, 'esES', 'Enredadera marchita por la escarcha', 'Un trozo de la gran enredadera espinosa de Rajacieno, ennegrecido por el frío del liche. Los chamanes jabaespines darían mucho por recuperarlo.', 0),
(7770006, 'esMX', 'Enredadera marchita por la escarcha', 'Un trozo de la gran enredadera espinosa de Rajacieno, ennegrecido por el frío del liche. Los chamanes jabaespines darían mucho por recuperarlo.', 0),
(7770006, 'frFR', 'Liane épineuse flétrie par le givre', 'Un morceau de la grande liane épineuse de Tranchebauge, noirci par le froid de la liche. Les chamans huranes donneraient cher pour le récupérer.', 0),
(7770006, 'koKR', '서리에 시든 가시덩굴', '리치의 냉기에 검게 시든 가시덩굴 조각입니다. 가시멧돼지 주술사라면 되찾기 위해 큰 대가를 치를 것입니다.', 0),
(7770006, 'ruRU', 'Побитая морозом колючая лоза', 'Обрывок огромной колючей лозы Иглошкурых, почерневшей от холода лича. Шаманы свинобразов дорого дали бы, чтобы вернуть его.', 0),
(7770007, 'deDE', 'Gesangbuch des Scharlachroten Klosters', 'Ein Gebetbuch aus der Klosterbibliothek, älter als der Kreuzzug. Seine Ränder sind voller sorgfältiger Notizen eines Mönchs.', 0),
(7770007, 'esES', 'Himnario del Monasterio Escarlata', 'Un libro de oraciones de la biblioteca del monasterio, más antiguo que la Cruzada. Sus márgenes están llenos de cuidadosas notas de un monje.', 0),
(7770007, 'esMX', 'Himnario del Monasterio Escarlata', 'Un libro de oraciones de la biblioteca del monasterio, más antiguo que la Cruzada. Sus márgenes están llenos de cuidadosas notas de un monje.', 0),
(7770007, 'frFR', 'Hymnaire du Monastère écarlate', 'Un livre de prières de la bibliothèque du monastère, plus ancien que la Croisade. Ses marges sont pleines des notes soigneuses d''un moine.', 0),
(7770007, 'koKR', '붉은십자군 수도원 찬송가집', '십자군보다 오래된 수도원 도서관의 기도서입니다. 여백에는 어느 수도사의 꼼꼼한 메모가 가득합니다.', 0),
(7770007, 'ruRU', 'Псалтырь Монастыря Алого ордена', 'Молитвенник из монастырской библиотеки, написанный еще до Алого ордена. Поля исписаны аккуратными заметками какого-то монаха.', 0),
(7770008, 'deDE', 'Knochenfetisch der Sandwüter', 'Ein Trollfetisch aus Knochen und Federn aus Zul''Farrak. Tran''rek sagt, er sei jetzt harmlos. Behalten würde er ihn trotzdem nicht.', 0),
(7770008, 'esES', 'Fetiche de hueso Furiarena', 'Un fetiche trol de hueso y plumas sacado de Zul''Farrak. Tran''rek dice que ahora es inofensivo. Aun así, él no lo guardaría.', 0),
(7770008, 'esMX', 'Fetiche de hueso Furiarena', 'Un fetiche trol de hueso y plumas sacado de Zul''Farrak. Tran''rek dice que ahora es inofensivo. Aun así, él no lo guardaría.', 0),
(7770008, 'frFR', 'Fétiche d''os furie-des-sables', 'Un fétiche troll d''os et de plumes pris à Zul''Farrak. Tran''rek dit qu''il est inoffensif désormais. Il ne le garderait pas pour autant.', 0),
(7770008, 'koKR', '성난모래부족 뼈 부적', '줄파락에서 가져온 뼈와 깃털로 된 트롤 부적입니다. 트란렉은 이제 해롭지 않다고 말하지만 자기가 갖고 있지는 않을 것입니다.', 0),
(7770008, 'ruRU', 'Костяной фетиш Песчаной Бури', 'Тролльий фетиш из костей и перьев, вынесенный из Зул''Фаррака. Тран''рек уверяет, что теперь он безвреден, но себе его оставлять не стал бы.', 0),
(7770009, 'deDE', 'Phiole mit reinem Wasser aus Maraudon', 'Wasser aus den Teichen nahe Zaetars Ruhestätte, wieder klar, seit die Prinzessin fort ist.', 0),
(7770009, 'esES', 'Vial de agua pura de Maraudon', 'Agua de las pozas cercanas al lugar de reposo de Zaetar, clara de nuevo ahora que la princesa ya no está.', 0),
(7770009, 'esMX', 'Vial de agua pura de Maraudon', 'Agua de las pozas cercanas al lugar de reposo de Zaetar, clara de nuevo ahora que la princesa ya no está.', 0),
(7770009, 'frFR', 'Fiole d''eau pure de Maraudon', 'De l''eau puisée près du lieu de repos de Zaetar, redevenue claire depuis la disparition de la princesse.', 0),
(7770009, 'koKR', '마라우돈의 맑은 물 약병', '재타르의 안식처 근처 웅덩이에서 길어 온 물입니다. 공주가 사라진 뒤로 다시 맑아졌습니다.', 0),
(7770009, 'ruRU', 'Склянка чистой воды Мародона', 'Вода из озер у места упокоения Зейтара. Она снова чиста, ведь принцессы больше нет.', 0),
(7770010, 'deDE', 'Abgeworfene Smaragddrachenschuppe', 'Eine kleine grüne Schuppe, die ein Drache aus Itharius'' Schwarm abgeworfen hat. Sie fühlt sich kühl an und riecht nach Regen.', 0),
(7770010, 'esES', 'Escama de dragón esmeralda', 'Una pequeña escama verde mudada por un dragón del vuelo de Itharius. Es fresca al tacto y huele a lluvia.', 0),
(7770010, 'esMX', 'Escama de dragón esmeralda', 'Una pequeña escama verde mudada por un dragón del vuelo de Itharius. Es fresca al tacto y huele a lluvia.', 0),
(7770010, 'frFR', 'Écaille de dragon d''émeraude', 'Une petite écaille verte perdue par un dragon du vol d''Itharius. Elle est fraîche au toucher et sent la pluie.', 0),
(7770010, 'koKR', '벗겨진 에메랄드 용 비늘', '이타리우스의 무리 중 한 마리가 떨군 작은 녹색 비늘입니다. 만지면 서늘하고 비 냄새가 납니다.', 0),
(7770010, 'ruRU', 'Сброшенная изумрудная чешуйка', 'Маленькая зеленая чешуйка, сброшенная одним из драконов стаи Итара. Прохладная на ощупь, пахнет дождем.', 0),
(7770011, 'deDE', 'Insignie der Schmetterschilde', 'Die Insignie einer Legion der Dunklen Horde aus der Schwarzfelsspitze. Ihr Besitzer wird sie nicht vermissen.', 0),
(7770011, 'esES', 'Distintivo del Escudo del Estigma', 'El distintivo de una legión de la Horda Oscura en la Cumbre de Roca Negra. Su dueño no lo echará de menos.', 0),
(7770011, 'esMX', 'Distintivo del Escudo del Estigma', 'El distintivo de una legión de la Horda Oscura en la Cumbre de Roca Negra. Su dueño no lo echará de menos.', 0),
(7770011, 'frFR', 'Insigne du Bouclier balafré', 'L''insigne d''une légion de la Horde noire au pic Blackrock. Son propriétaire ne le regrettera pas.', 0),
(7770011, 'koKR', '방패부대 휘장', '검은바위 첨탑에 있는 어둠의 호드 군단의 휘장입니다. 주인은 아쉬워하지 않을 것입니다.', 0),
(7770011, 'ruRU', 'Знак легиона Изрубленного Щита', 'Знак одного из легионов Черной Орды с Пика Черной горы. Его владельцу он больше не понадобится.', 0),
(7770012, 'deDE', 'Seeperle von Caer Darrow', 'Eine schwarze Perle aus dem See um Caer Darrow. Eva sagt, die Fischer hätten solche gefunden, bevor der Kult kam.', 0),
(7770012, 'esES', 'Perla del lago de Castel Darrow', 'Una perla negra del lago que rodea Castel Darrow. Eva dice que los pescadores las encontraban antes de que llegara el Culto.', 0),
(7770012, 'esMX', 'Perla del lago de Castel Darrow', 'Una perla negra del lago que rodea Castel Darrow. Eva dice que los pescadores las encontraban antes de que llegara el Culto.', 0),
(7770012, 'frFR', 'Perle du lac de Caer Darrow', 'Une perle noire du lac qui entoure Caer Darrow. Eva dit que les pêcheurs en trouvaient avant l''arrivée du Culte.', 0),
(7770012, 'koKR', '카엘 다로우 호수 진주', '카엘 다로우를 둘러싼 호수에서 나온 검은 진주입니다. 에바는 교단이 오기 전에는 어부들이 이런 진주를 찾곤 했다고 말합니다.', 0),
(7770012, 'ruRU', 'Озерная жемчужина Каэр Дарроу', 'Черная жемчужина из озера вокруг Каэр Дарроу. Ева говорит, что рыбаки находили такие, пока не пришел Культ.', 0),
(7770013, 'deDE', 'Angelaufenes Abzeichen der Silbernen Hand', 'Ein Abzeichen des in Stratholme gegründeten Ordens der Silbernen Hand, gefunden in den Ruinen.', 0),
(7770013, 'esES', 'Insignia deslustrada de la Mano de Plata', 'Una insignia de la Orden de la Mano de Plata, fundada en Stratholme, hallada en las ruinas.', 0),
(7770013, 'esMX', 'Insignia deslustrada de la Mano de Plata', 'Una insignia de la Orden de la Mano de Plata, fundada en Stratholme, hallada en las ruinas.', 0),
(7770013, 'frFR', 'Insigne terni de la Main d''argent', 'Un insigne de l''ordre de la Main d''argent, fondé à Stratholme, trouvé dans les ruines.', 0),
(7770013, 'koKR', '빛바랜 은빛 성기사단 휘장', '스트라솔름에서 창설된 은빛 성기사단의 휘장으로, 폐허에서 발견되었습니다.', 0),
(7770013, 'ruRU', 'Потускневший значок Серебряной Длани', 'Значок Ордена Серебряной Длани, основанного в Стратхольме. Найден среди руин.', 0),
(7770014, 'deDE', 'Siegel der Schwarzfaustlegion', 'Das Siegel der Schwarzfaustlegion, der Elite der Dunklen Horde. Morgans Wacht und Kargath kaufen sie beide als Beweis.', 0),
(7770014, 'esES', 'Sello de la Legión Puño Negro', 'El sello de la Legión Puño Negro, la élite de la Horda Oscura. La Vigilia de Morgan y Kargath los compran como prueba.', 0),
(7770014, 'esMX', 'Sello de la Legión Puño Negro', 'El sello de la Legión Puño Negro, la élite de la Horda Oscura. La Vigilia de Morgan y Kargath los compran como prueba.', 0),
(7770014, 'frFR', 'Sceau de la légion Main-noire', 'Le sceau de la légion Main-noire, l''élite de la Horde noire. La Veille de Morgan et Kargath les achètent tous deux comme preuve.', 0),
(7770014, 'koKR', '검은손부대 인장', '어둠의 호드 정예인 검은손부대의 인장입니다. 모건의 망루와 카르가스 모두 증거로 사들입니다.', 0),
(7770014, 'ruRU', 'Печать легиона Чернорука', 'Печать легиона Чернорука, элиты Черной Орды. Дозор Морганы и Каргат покупают такие в качестве доказательства.', 0),
(7770015, 'deDE', 'Teufelsversengte Schuppe Nazans', 'Eine Schuppe von Nazan, dem Teufelsdrachen, der die Bollwerke bewachte, noch warm vom Teufelsfeuer.', 0),
(7770015, 'esES', 'Escama vil de Nazan', 'Una escama de Nazan, el dragón vil que guardaba las murallas, todavía caliente por el fuego vil.', 0),
(7770015, 'esMX', 'Escama vil de Nazan', 'Una escama de Nazan, el dragón vil que guardaba las murallas, todavía caliente por el fuego vil.', 0),
(7770015, 'frFR', 'Écaille gangrenée de Nazan', 'Une écaille de Nazan, le dragon gangrené qui gardait les remparts, encore chaude de gangrefeu.', 0),
(7770015, 'koKR', '나잔의 지옥불 비늘', '성루를 지키던 지옥 용 나잔의 비늘로, 아직 지옥불의 온기가 남아 있습니다.', 0),
(7770015, 'ruRU', 'Опаленная Скверной чешуя Назана', 'Чешуя Назана, дракона Скверны, охранявшего бастионы. Она все еще хранит тепло огня Скверны.', 0),
(7770016, 'deDE', 'Geflochtener Glücksbringer eines Befreiten', 'Ein Glücksbringer aus Sumpfschilf, geflochten von einem befreiten Sklaven für den, der ihn befreit hat.', 0),
(7770016, 'esES', 'Amuleto tejido de un esclavo liberado', 'Un amuleto de juncos tejido por un esclavo liberado de los recintos para quien lo liberó.', 0),
(7770016, 'esMX', 'Amuleto tejido de un esclavo liberado', 'Un amuleto de juncos tejido por un esclavo liberado de los recintos para quien lo liberó.', 0),
(7770016, 'frFR', 'Charme tressé d''un esclave libéré', 'Un charme de roseaux tressé par un esclave libéré des enclos, pour celui qui l''a délivré.', 0),
(7770016, 'koKR', '해방된 노예의 엮은 부적', '노예 우리에서 풀려난 이가 자신을 구해 준 사람을 위해 늪 갈대로 엮은 부적입니다.', 0),
(7770016, 'ruRU', 'Плетеный оберег освобожденного раба', 'Оберег из болотного тростника. Его сплел один из рабов, выпущенных из загонов, для того, кто их освободил.', 0),
(7770017, 'deDE', 'Gebetsperlen der Auchenai', 'Gebetsperlen der Draenei, aus den Auchenaikrypta geborgen. Die Ältesten haben sie erneut gesegnet.', 0),
(7770017, 'esES', 'Cuentas de oración Auchenai', 'Cuentas de oración draenei sacadas de las Criptas Auchenai. Los ancianos han vuelto a bendecirlas.', 0),
(7770017, 'esMX', 'Cuentas de oración Auchenai', 'Cuentas de oración draenei sacadas de las Criptas Auchenai. Los ancianos han vuelto a bendecirlas.', 0),
(7770017, 'frFR', 'Chapelet auchenaï', 'Un chapelet draeneï rapporté des cryptes Auchenaï. Les anciens l''ont de nouveau béni.', 0),
(7770017, 'koKR', '아키나이 기도 염주', '아키나이 납골당에서 가져온 드레나이 기도 염주입니다. 장로들이 다시 축복했습니다.', 0),
(7770017, 'ruRU', 'Аукенайские четки', 'Дренейские четки, вынесенные из Аукенайских гробниц. Старейшины благословили их заново.', 0),
(7770018, 'deDE', 'Phiole mit Sand aus dem alten Hügelland', 'Sand aus dem Zeitweg des alten Hügellands von Hillsbrad in einer verkorkten Phiole. Er rieselt etwas langsamer, als er sollte.', 0),
(7770018, 'esES', 'Vial de arena de Trabalomas antiguo', 'Arena de la senda del tiempo de Trabalomas antiguo en un vial tapado. Cae un poco más despacio de lo que debería.', 0),
(7770018, 'esMX', 'Vial de arena de Trabalomas antiguo', 'Arena de la senda del tiempo de Trabalomas antiguo en un vial tapado. Cae un poco más despacio de lo que debería.', 0),
(7770018, 'frFR', 'Fiole de sable de Hautebrande d''antan', 'Du sable de la voie temporelle de Hautebrande d''antan dans une fiole bouchée. Il tombe un peu plus lentement qu''il ne devrait.', 0),
(7770018, 'koKR', '옛 힐스브래드 모래 약병', '옛 힐스브래드 시간의 길에서 가져온 모래를 마개 달린 약병에 담았습니다. 모래가 평소보다 조금 느리게 떨어집니다.', 0),
(7770018, 'ruRU', 'Склянка песка Старых предгорий Хилсбрада', 'Песок из временного потока Старых предгорий Хилсбрада в закупоренной склянке. Он сыплется чуть медленнее, чем должен.', 0),
(7770019, 'deDE', 'Sonnenfeder der Arakkoa', 'Eine lange goldene Feder, wie sie die Arakkoa trugen, bevor sich die Sethekk den Schatten zuwandten.', 0),
(7770019, 'esES', 'Pluma solar arakkoa', 'Una larga pluma dorada como las que llevaban los arakkoa antes de que los Sethekk se volvieran hacia las sombras.', 0),
(7770019, 'esMX', 'Pluma solar arakkoa', 'Una larga pluma dorada como las que llevaban los arakkoa antes de que los Sethekk se volvieran hacia las sombras.', 0),
(7770019, 'frFR', 'Plume solaire d''arakkoa', 'Une longue plume dorée comme en portaient les arakkoa avant que les Sethekk ne se tournent vers l''ombre.', 0),
(7770019, 'koKR', '아라코아 태양 깃털', '세데크가 어둠에 빠지기 전 아라코아가 달던 긴 황금 깃털입니다.', 0),
(7770019, 'ruRU', 'Солнечное перо аракоа', 'Длинное золотое перо, какие носили аракоа до того, как сетекки обратились к тьме.', 0),
(7770020, 'deDE', 'Schuppe des ewigen Drachen', 'Eine schwarze Schuppe, abgeworfen von einem Drachen des ewigen Drachenschwarms. Bei jedem Blick wirkt sie neuer.', 0),
(7770020, 'esES', 'Escama de dragón infinito', 'Una escama negra mudada por un miembro del vuelo infinito. Cada vez que la miras parece más nueva.', 0),
(7770020, 'esMX', 'Escama de dragón infinito', 'Una escama negra mudada por un miembro del vuelo infinito. Cada vez que la miras parece más nueva.', 0),
(7770020, 'frFR', 'Écaille de dragon infini', 'Une écaille noire perdue par un membre du vol draconique infini. Elle paraît plus neuve à chaque regard.', 0),
(7770020, 'koKR', '무한의 용 비늘', '무한의 용군단이 떨군 검은 비늘입니다. 볼 때마다 더 새것처럼 보입니다.', 0),
(7770020, 'ruRU', 'Чешуя Бесконечного дракона', 'Черная чешуя, сброшенная одним из драконов Бесконечности. С каждым взглядом она кажется все новее.', 0),
(7770021, 'deDE', 'Messingventilrad aus dem Echsenkessel', 'Ein Ventilrad von einer der Pumpen der Dampfkammer. Diese Pumpe dreht sich nie wieder.', 0),
(7770021, 'esES', 'Volante de válvula de Colmillo Torcido', 'Un volante de válvula de una de las bombas de la Cámara de Vapor. Esa bomba no volverá a girar.', 0),
(7770021, 'esMX', 'Volante de válvula de Colmillo Torcido', 'Un volante de válvula de una de las bombas de la Cámara de Vapor. Esa bomba no volverá a girar.', 0),
(7770021, 'frFR', 'Volant de vanne de Glissecroc', 'Un volant de vanne pris sur une pompe du Caveau de la vapeur. Cette pompe ne tournera plus.', 0),
(7770021, 'koKR', '갈퀴송곳니 황동 밸브 손잡이', '증기고의 펌프에서 떼어 낸 밸브 손잡이입니다. 그 펌프는 다시는 돌지 않을 것입니다.', 0),
(7770021, 'ruRU', 'Латунный вентиль Кривого Клыка', 'Вентиль с одного из насосов Парового подземелья. Этот насос больше не заработает.', 0),
(7770022, 'deDE', 'Bruchstück von Kargaths Messerfaust', 'Ein abgebrochenes Stück der Klinge, die Kargath anstelle seiner Hand trug.', 0),
(7770022, 'esES', 'Fragmento de la hoja de Kargath', 'Un trozo roto de la hoja que Kargath llevaba en lugar de la mano.', 0),
(7770022, 'esMX', 'Fragmento de la hoja de Kargath', 'Un trozo roto de la hoja que Kargath llevaba en lugar de la mano.', 0),
(7770022, 'frFR', 'Fragment de la lame de Kargath', 'Un morceau brisé de la lame que Kargath portait à la place de sa main.', 0),
(7770022, 'koKR', '카르가스의 칼날 파편', '카르가스가 손 대신 달고 있던 칼날의 부러진 조각입니다.', 0),
(7770022, 'ruRU', 'Обломок клинка Каргата Острорука', 'Сломанный кусок клинка, который Каргат носил вместо руки.', 0),
(7770023, 'deDE', 'Arkan gezogene Blüte', 'Eine Blume, gezogen unter den Arkanlampen der Botanika und durch Vargoths Zauber erhalten. Sie leuchtet schwach violett.', 0),
(7770023, 'esES', 'Flor cultivada con arcano', 'Una flor cultivada bajo las lámparas arcanas del Invernáculo y conservada por un hechizo de Vargoth. Brilla con un tenue tono violeta.', 0),
(7770023, 'esMX', 'Flor cultivada con arcano', 'Una flor cultivada bajo las lámparas arcanas del Invernáculo y conservada por un hechizo de Vargoth. Brilla con un tenue tono violeta.', 0),
(7770023, 'frFR', 'Fleur cultivée par l''arcane', 'Une fleur cultivée sous les lampes arcaniques de la Botanica et préservée par un sort de Vargoth. Elle luit d''un faible éclat violet.', 0),
(7770023, 'koKR', '비전으로 키운 꽃', '신록의 정원 비전 등불 아래에서 자라 바르고스의 주문으로 보존된 꽃입니다. 희미한 보랏빛을 띱니다.', 0),
(7770023, 'ruRU', 'Цветок, выращенный магией', 'Цветок, выращенный под чародейскими лампами Ботаники и сохраненный заклинанием Варгота. Он слабо светится фиолетовым.', 0),
(7770024, 'deDE', 'Millhaus'' Ersatzzauberfokus', 'Ein Kristallfokus, den Millhaus Manasturm angeblich nicht mehr braucht. Er summt selbstgefällig.', 0),
(7770024, 'esES', 'Foco de repuesto de Molino', 'Un foco de cristal que Molino Tormenta de maná asegura no necesitar ya. Zumba con aire de suficiencia.', 0),
(7770024, 'esMX', 'Foco de repuesto de Molino', 'Un foco de cristal que Molino Tormenta de maná asegura no necesitar ya. Zumba con aire de suficiencia.', 0),
(7770024, 'frFR', 'Focaliseur de rechange de Milhouse', 'Un focaliseur de cristal dont Milhouse Tempête-de-mana affirme ne plus avoir besoin. Il bourdonne d''un air suffisant.', 0),
(7770024, 'koKR', '밀하우스의 예비 주문 집중기', '밀하우스 마나스톰이 이제 필요 없다고 우기는 수정 집중기입니다. 잘난 체하듯 웅웅거립니다.', 0),
(7770024, 'ruRU', 'Запасной фокус Миллхауса', 'Кристаллический фокус, который, по словам Миллхауса Манашторма, ему больше не нужен. Он самодовольно гудит.', 0),
(7770025, 'deDE', 'Glasrose aus Sonnenweiten', 'Eine Rose aus mundgeblasenem rotem Glas, gefertigt von den nach Sonnenweiten zurückgekehrten Kunsthandwerkern.', 0),
(7770025, 'esES', 'Rosa de cristal de Tramo del Sol', 'Una rosa de cristal rojo soplado, hecha por los artesanos que regresaron a Tramo del Sol.', 0),
(7770025, 'esMX', 'Rosa de cristal de Tramo del Sol', 'Una rosa de cristal rojo soplado, hecha por los artesanos que regresaron a Tramo del Sol.', 0),
(7770025, 'frFR', 'Rose de verre des Confins du soleil', 'Une rose de verre rouge soufflé, créée par les artisans revenus aux Confins du soleil.', 0),
(7770025, 'koKR', '태양너울 유리 장미', '태양너울로 돌아온 장인들이 붉은 유리를 불어 만든 장미입니다.', 0),
(7770025, 'ruRU', 'Стеклянная роза Солнечного Края', 'Роза из выдувного красного стекла, созданная мастерами, вернувшимися в Солнечный Край.', 0),
(7770026, 'deDE', 'Leykristall aus Kaltarra', 'Ein Kristall, der dort wuchs, wo eine Leylinie dicht unter der Oberfläche von Kaltarra verläuft. Seit der Nexus verstummt ist, ist er still.', 0),
(7770026, 'esES', 'Cristal Ley de Gelidar', 'Un cristal que creció donde una línea Ley pasa cerca de la superficie de Gelidar. Quedó en calma desde que el Nexo enmudeció.', 0),
(7770026, 'esMX', 'Cristal Ley de Gelidar', 'Un cristal que creció donde una línea Ley pasa cerca de la superficie de Gelidar. Quedó en calma desde que el Nexo enmudeció.', 0),
(7770026, 'frFR', 'Cristal tellurique de Frimarra', 'Un cristal né là où une ligne tellurique affleure à Frimarra. Il s''est tu depuis que le Nexus est silencieux.', 0),
(7770026, 'koKR', '콜다라 지맥 수정', '콜다라 지표 가까이 지맥이 지나는 곳에서 자란 수정입니다. 마력의 탑이 잠잠해진 뒤로 조용해졌습니다.', 0),
(7770026, 'ruRU', 'Силовой кристалл Хладарры', 'Кристалл, выросший там, где силовая линия подходит близко к поверхности Хладарры. Он затих с тех пор, как замолчал Нексус.', 0),
(7770027, 'deDE', 'Juwelenbesetzter Neruberchitin', 'Eine Platte aus Neruberchitin, besetzt mit winzigen Edelsteinen, aus den Hallen des alten Königreichs.', 0),
(7770027, 'esES', 'Quitina nerubiana con gemas', 'Una placa de quitina nerubiana engastada con gemas diminutas, de las salas del antiguo reino.', 0),
(7770027, 'esMX', 'Quitina nerubiana con gemas', 'Una placa de quitina nerubiana engastada con gemas diminutas, de las salas del antiguo reino.', 0),
