(7770028, 'deDE', 'Siegelring eines Schattenhammerkultisten', 'Ein Siegelring von einem der Anhänger Jedoga Schattensuchers. Am besten schnell verkaufen.', 0),
(7770028, 'esES', 'Sello de cultor crepuscular', 'Un anillo de sello tomado de un seguidor de Jedoga Buscasombras. Mejor venderlo pronto.', 0),
(7770028, 'esMX', 'Sello de cultor crepuscular', 'Un anillo de sello tomado de un seguidor de Jedoga Buscasombras. Mejor venderlo pronto.', 0),
