(7770032, 'esMX', 'Esquirla de la corona de Ymiron', 'Un fragmento de la corona de hierro del rey vrykul.', 0),
(7770032, 'frFR', 'Éclat de la couronne d''Ymiron', 'Un fragment de la couronne de fer du roi vrykul.', 0),
