(7770034, 'esES', 'Piedra marcada por el rayo de Loken', 'Una piedra de las Cámaras de Relámpagos, marcada con dibujos crepitantes por el poder de Loken.', 0),
(7770034, 'esMX', 'Piedra marcada por el rayo de Loken', 'Una piedra de las Cámaras de Relámpagos, marcada con dibujos crepitantes por el poder de Loken.', 0),
(7770034, 'frFR', 'Pierre foudroyée de Loken', 'Une pierre des Salles de foudre, marquée de motifs crépitants par le pouvoir de Loken.', 0),
(7770034, 'koKR', '로켄의 번개 자국 돌', '번개의 전당에서 나온 돌로, 로켄의 힘으로 번개 무늬가 새겨져 있습니다.', 0),
(7770034, 'ruRU', 'Опаленный молниями камень Локена', 'Камень из Чертогов Молний с потрескивающими узорами, выжженными силой Локена.', 0),
