-- Names and descriptions of the reactivity gift items for every client
-- locale the module supports. Portuguese has no 3.3.5 locale, so it stays
-- on the English text of item_template. esMX shares the esES text.
--
-- Place, creature and faction names follow the stock locale tables. Run
-- after 20261103_reactivity_items.sql.
SET NAMES utf8mb4;

DELETE FROM `item_template_locale` WHERE `ID` BETWEEN 7770000 AND 7770098;
